```javascript
const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let p = 0;

const N = input[p++];
const M = input[p++];

const cars = input.slice(p, p + N);
p += N;
const mechanics = input.slice(p, p + M);

cars.sort((a, b) => b - a);

const values = new Array(M).fill(0);
const steps = mechanics;

let answer = 0n;

for (let k = 0; k < N; k++) {
  const coefficient = values[0];
  answer += BigInt(cars[k]) * BigInt(coefficient);

  const step = steps[0];
  const updated = coefficient + step;
  let i = 0;

  while (true) {
    const left = 2 * i + 1;
    if (left >= M) break;

    const right = left + 1;
    let child = left;
    if (right < M && values[right] < values[left]) child = right;
    if (values[child] >= updated) break;

    values[i] = values[child];
    steps[i] = steps[child];
    i = child;
  }

  values[i] = updated;
  steps[i] = step;
}

console.log(answer.toString());
